import {createWorld} from './world.js';
'use strict';
const $=id=>document.getElementById(id),canvas=$('scene'),world=createWorld(canvas);
const KEY='roadster-flight-u3d-v2';let records=[],storageOK=true,view='rank',playerName='';
try{const data=JSON.parse(localStorage.getItem(KEY)||'{}');records=Array.isArray(data.records)?data.records.filter(r=>r&&typeof r.name==='string'&&Number.isFinite(r.distance)&&r.distance>=0).slice(0,100):[];playerName=typeof data.name==='string'?data.name:'';}catch{storageOK=false;}
$('player').value=playerName;
const input={up:false,down:false,left:false,right:false,boost:false};let state='ready',paused=false,accumulator=0,last=0,simTime=0,flight=null,W=900,H=490,scale=5,camX=0,camY=0;
for(let i=0;i<10;i++)$('fuel').appendChild(document.createElement('b'));
function persist(){try{localStorage.setItem(KEY,JSON.stringify({name:playerName,records}));}catch{storageOK=false;}$('storageNote').textContent=storageOK?'U 形赛道独立档案，仅保存在此浏览器。以起飞点到落地点的地面直线距离计分，非全球榜单。':'浏览器未允许保存，当前记录仅在本次页面有效。';}
function renderRecords(){const sorted=view==='rank'?[...records].sort((a,b)=>b.distance-a.distance):records;const best=[...records].sort((a,b)=>b.distance-a.distance)[0];$('best').textContent=best?best.distance.toFixed(1):'—';$('bestName').textContent=best?best.name+' · '+new Date(best.time).toLocaleDateString('zh-CN'):'等待第一位驾驶员';$('runCount').textContent=String(records.length).padStart(2,'0');$('records').replaceChildren();if(!sorted.length){const e=document.createElement('div');e.className='empty';e.textContent='还没有飞行记录。你的第一次飞跃，将从这里开始。';$('records').append(e);}sorted.slice(0,5).forEach((r,i)=>{const row=document.createElement('div');row.className='row';for(const [tag,text]of [['span',String(i+1).padStart(2,'0')],['b',r.name],['strong',r.distance.toFixed(1)+' m']]){const e=document.createElement(tag);e.textContent=text;row.append(e);}$('records').append(row);});}
function clearInput(){for(const k in input){input[k]=false;$(k).classList.remove('pressed');}}
function setPause(p){if(!['run','flight'].includes(state))return;paused=p;$('pauseFlag').hidden=!p;clearInput();$('pause').textContent=p?'继续':'暂停';$('phase').textContent=p?'FLIGHT PAUSED':state==='run'?'ACCELERATING':'FLIGHT IN PROGRESS';}
function start(){if(!world.ready)return;playerName=$('player').value.trim();if(!playerName){$('message').textContent='请输入驾驶员名称';$('player').focus();return;}$('message').textContent='';$('player').blur();persist();flight={x:-90,y:1.05,z:0,vx:0,vy:0,vz:0,a:0,av:0,rv:0,rollTotal:0,q:{x:0,y:0,z:0,w:1},s:0,runSpeed:0,fuel:100,t:0,distance:0};state='run';paused=false;$('pauseFlag').hidden=true;simTime=0;accumulator=0;clearInput();$('pause').textContent='暂停';$('overlay').classList.add('hidden');$('phase').textContent='ACCELERATING';}
function finish(){state='end';clearInput();const distance=Math.round(Math.hypot(flight.x,flight.z)*10)/10,best=Math.max(0,...records.map(r=>r.distance));records.unshift({name:playerName,distance,time:Date.now(),dx:flight.x,dz:flight.z,landing:qv(flight.q,{x:0,y:1,z:0}).y>.75?'smooth':'rough'});records=records.slice(0,100);persist();renderRecords();$('cardEyebrow').textContent=distance>best?'NEW PERSONAL RECORD':'FLIGHT COMPLETED';$('cardTitle').textContent=distance.toFixed(1)+' 米';$('cardText').textContent=(qv(flight.q,{x:0,y:1,z:0}).y>.75?'平稳触地。':'触地时车身倾斜，下次试着提前调平。')+' 前后 '+flight.x.toFixed(1)+' m / 左右 '+flight.z.toFixed(1)+' m。已保存，再挑战一次？';$('startButton').textContent='再飞一次 ↗';$('overlay').classList.remove('hidden','ready-screen');$('phase').textContent='FLIGHT COMPLETED';}
function qm(a,b){return {x:a.w*b.x+a.x*b.w+a.y*b.z-a.z*b.y,y:a.w*b.y-a.x*b.z+a.y*b.w+a.z*b.x,z:a.w*b.z+a.x*b.y-a.y*b.x+a.z*b.w,w:a.w*b.w-a.x*b.x-a.y*b.y-a.z*b.z};}
function qv(q,v){const t=qm(q,{...v,w:0});return qm(t,{x:-q.x,y:-q.y,z:-q.z,w:q.w});}
function terrainHeight(x,z){if(Math.abs(z)>5)return 0;const join=-28*Math.sin(1.35);let u;if(x>=join&&x<=0)u=x-join;else if(x<=-100&&x>=-100+join)u=-100-x;else return 0;return 28-Math.sqrt(Math.max(0,28*28-u*u));}
function step(dt){if(paused||!flight||!['run','flight'].includes(state))return;simTime+=dt;const f=flight;f.t+=dt;
if(state==='run'){f.runSpeed=Math.min(43,f.runSpeed+23*dt);f.s+=f.runSpeed*dt;const flat=90-28*Math.sin(1.35);const theta=Math.max(0,Math.min(1.35,(f.s-flat)/28));f.x=f.s<flat?-90+f.s:-28*Math.sin(1.35)+28*Math.sin(theta);f.y=1.05+28*(1-Math.cos(theta));f.a=theta;f.q={x:0,y:0,z:Math.sin(theta/2),w:Math.cos(theta/2)};f.vx=f.runSpeed*Math.cos(theta);f.vy=f.runSpeed*Math.sin(theta);if(f.s>=flat+28*1.35){f.x=0;state='flight';$('phase').textContent='FLIGHT IN PROGRESS';}return;}
const pitch=(input.up?1:0)-(input.down?1:0),roll=(input.right?1:0)-(input.left?1:0);f.av+=(pitch*5.5-f.av*3.5)*dt;f.rv+=(roll*9-f.rv*3)*dt;f.rollTotal+=f.rv*dt;
const da=f.av*dt,dr=f.rv*dt;f.q=qm(qm(f.q,{x:Math.sin(dr/2),y:0,z:0,w:Math.cos(dr/2)}),{x:0,y:0,z:Math.sin(da/2),w:Math.cos(da/2)});const norm=Math.hypot(f.q.x,f.q.y,f.q.z,f.q.w);for(const k of ['x','y','z','w'])f.q[k]/=norm;
const forward=qv(f.q,{x:1,y:0,z:0}),up=qv(f.q,{x:0,y:1,z:0}),side=qv(f.q,{x:0,y:0,z:1});const speed=Math.hypot(f.vx,f.vy,f.vz),dotUp=(up.x*f.vx+up.y*f.vy+up.z*f.vz)/Math.max(1,speed),dotSide=(side.x*f.vx+side.y*f.vy+side.z*f.vz)/Math.max(1,speed);const lift=Math.max(-7,Math.min(12,-speed*speed*.016*dotUp)),drag=.0009*speed*(1+6*dotUp*dotUp+3*dotSide*dotSide);let thrust=0;if(input.boost&&f.fuel>0){const used=Math.min(f.fuel,100/6*dt);thrust=used/(100/6*dt)*19;f.fuel=Math.max(0,f.fuel-used);}
const old={x:f.x,y:f.y,z:f.z};f.vx+=(thrust*(forward.x+.55*up.x)+lift*up.x-drag*f.vx)*dt;f.vy+=(thrust*(forward.y+.55*up.y)+lift*up.y-drag*f.vy-9.81)*dt;f.vz+=(thrust*(forward.z+.55*up.z)+lift*up.z-drag*f.vz)*dt;f.x+=f.vx*dt;f.y+=f.vy*dt;f.z+=f.vz*dt;f.distance=Math.hypot(f.x,f.z);f.a=Math.atan2(forward.y,Math.hypot(forward.x,forward.z));
if(f.y<=terrainHeight(f.x,f.z)+1.05){let lo=0,hi=1;for(let i=0;i<18;i++){const mid=(lo+hi)/2,x=old.x+(f.x-old.x)*mid,z=old.z+(f.z-old.z)*mid,y=old.y+(f.y-old.y)*mid;if(y>terrainHeight(x,z)+1.05)lo=mid;else hi=mid;}const t=hi;f.x=old.x+(f.x-old.x)*t;f.z=old.z+(f.z-old.z)*t;f.y=terrainHeight(f.x,f.z)+1.05;f.distance=Math.hypot(f.x,f.z);finish();}}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;world.resize(W,H);}
function draw(){const f=flight||{x:-65,y:1.05,z:0,a:0,q:{x:0,y:0,z:0,w:1},fuel:100,vx:0,vy:0,vz:0,rollTotal:0};world.update(f,state,state==='flight'&&!paused&&input.boost&&f.fuel>0,paused,simTime);$('distance').textContent=(f.distance||0).toFixed(1);$('fuelLabel').textContent=Math.ceil(f.fuel)+'%';[...$('fuel').children].forEach((el,i)=>el.style.background=f.fuel>i*10?'#ed413b':'#343139');$('height').textContent=Math.max(0,f.y-1.05).toFixed(1);$('speed').textContent=Math.round(Math.hypot(f.vx,f.vy,f.vz)*3.6);$('pitch').textContent=Math.round(f.a*180/Math.PI);$('lateral').textContent=(state==='run'||state==='ready'?0:f.z).toFixed(1);$('forward').textContent=(state==='run'||state==='ready'?0:f.x).toFixed(1);$('rollAngle').textContent=Math.round(f.rollTotal*180/Math.PI);drawMap(f);}
function drawMap(f){const c=$('map'),g=c.getContext('2d'),w=110,h=88;g.clearRect(0,0,w,h);g.fillStyle='#0a0d12c9';g.fillRect(0,0,w,h);const radius=Math.max(100,Math.abs(f.x)*1.25,Math.abs(f.z)*1.25),px=55+f.x/radius*40,pz=44+f.z/radius*31;g.strokeStyle='#4d5464';g.lineWidth=.5;g.beginPath();g.moveTo(10,44);g.lineTo(100,44);g.moveTo(55,9);g.lineTo(55,79);g.stroke();g.strokeStyle='#ff5858';g.lineWidth=1.5;g.beginPath();g.moveTo(55,44);g.lineTo(px,pz);g.stroke();g.fillStyle='#fff';g.beginPath();g.arc(px,pz,2.5,0,Math.PI*2);g.fill();g.fillStyle='#939bad';g.font='8px Arial';g.fillText('前后 →',68,12);g.fillText('起点',38,54);g.fillText(Math.round(radius)+'m',8,82);}
function frame(t){if(!last)last=t;accumulator+=Math.min((t-last)/1000,.08);last=t;while(accumulator>=1/120){step(1/120);accumulator-=1/120;}draw();requestAnimationFrame(frame);}
for(const key of ['up','down','left','right','boost']){const el=$(key);el.addEventListener('pointerdown',e=>{e.preventDefault();if(paused)return;input[key]=true;el.classList.add('pressed');el.setPointerCapture(e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,()=>{input[key]=false;el.classList.remove('pressed');});}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName)||$('helpDialog').open)return;const k={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',KeyA:'left',KeyD:'right',KeyW:'up',KeyS:'down',Space:'boost'}[e.code];if(k){e.preventDefault();if(!paused){input[k]=true;$(k).classList.add('pressed');}}if(e.code==='KeyP'&&!e.repeat)setPause(!paused);});document.addEventListener('keyup',e=>{const k={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',KeyA:'left',KeyD:'right',KeyW:'up',KeyS:'down',Space:'boost'}[e.code];if(k){input[k]=false;$(k).classList.remove('pressed');}});window.addEventListener('blur',()=>{clearInput();setPause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden)setPause(true);});$('pause').onclick=()=>setPause(!paused);$('startForm').onsubmit=e=>{e.preventDefault();start();};$('rankTab').onclick=()=>{view='rank';$('rankTab').classList.add('active');$('recentTab').classList.remove('active');renderRecords();};$('recentTab').onclick=()=>{view='recent';$('recentTab').classList.add('active');$('rankTab').classList.remove('active');renderRecords();};$('viewToggle').onclick=()=>{const overview=world.toggleView();$('viewToggle').textContent=overview?'跟随汽车 ↗':'查看 U 形跳台 ↗';};$('help').onclick=()=>{setPause(true);$('helpDialog').showModal();};$('closeHelp').onclick=()=>$('helpDialog').close();new ResizeObserver(resize).observe(canvas);renderRecords();persist();resize();requestAnimationFrame(frame);
